{"code":"import json, glob, math
from pathlib import Path
import numpy as np
from scipy.optimize import minimize, curve_fit
hist=[]
for f in glob.glob('bench/logs/**/runner_state.json', recursive=True):
    raw=Path(f).read_text(errors='ignore')
    if 'novel_critical_history' not in raw: continue
    try: data=json.loads(raw)
    except Exception: continue
    vals=[]
    def walk(o):
        if isinstance(o,dict):
            for k,v in o.items():
                if k=='novel_critical_history' and isinstance(v,list) and all(isinstance(x,(int,float)) for x in v): vals.append([float(x) for x in v])
                walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(data)
    for v in vals:
        if len(v)>=3: hist.append(v)
print('histories', len(hist), 'files', len(set()))
# Use per-round mean across histories aligned by index for rounds with >=5 obs
maxlen=max(map(len,hist))
t=[]; y=[]; nobs=[]
for i in range(maxlen):
    vals=[h[i] for h in hist if len(h)>i]
    if len(vals)>=5:
        t.append(i); y.append(sum(vals)/len(vals)); nobs.append(len(vals))
print('aligned_points', len(t))
print('t y n first15')
for row in list(zip(t,y,nobs))[:15]: print(row)
t=np.array(t,dtype=float); y=np.array(y,dtype=float); w=np.array(nobs,dtype=float)
# weighted SSE fits: pure decay c*r^t, and floor+b + c*r^t. constrain via transform? use bounds curve_fit
def pure(t,c,r): return c*(r**t)
def floor(t,b,c,r): return b + c*(r**t)
popt0,_=curve_fit(pure,t,y,p0=(max(y),0.7),bounds=([0,0],[100,0.999]),sigma=1/np.sqrt(w),absolute_sigma=False,maxfev=10000)
popt1,_=curve_fit(floor,t,y,p0=(0.1,max(y),0.7),bounds=([0,0,0],[100,100,0.999]),sigma=1/np.sqrt(w),absolute_sigma=False,maxfev=10000)
for name,fn,popt,k in [('pure',pure,popt0,2),('floor',floor,popt1,3)]:
    resid=y-fn(t,*popt); sse=float(np.sum(w*resid*resid)); aic=len(y)*math.log(sse/len(y))+2*k
    print(name,'params',popt,'weighted_sse',sse,'AIC_like',aic)
print('delta_AIC pure-floor', (len(y)*math.log(float(np.sum(w*(y-pure(t,*popt0))**2))/len(y))+4) - (len(y)*math.log(float(np.sum(w*(y-floor(t,*popt1))**2))/len(y))+6))
# Poisson MLE on all observations as independent with shared mu(t)
obs=[]
for h in hist:
    for i,val in enumerate(h): obs.append((i,val))
to=np.array([x for x,_ in obs],float); yo=np.array([v for _,v in obs],float)
def nll_p(theta, floor_model):
    if floor_model:
        b,c,r=theta; mu=b+c*(r**to)
    else:
        c,r=theta; mu=c*(r**to)
    if np.any(mu<=0) or np.any(~np.isfinite(mu)): return 1e100
    return float(np.sum(mu-yo*np.log(mu))) # constants omitted
res0=minimize(lambda th:nll_p(th,False), [max(yo.mean(),.1),.7], bounds=[(1e-9,100),(1e-9,.999)])
res1=minimize(lambda th:nll_p(th,True), [.05,max(yo.mean(),.1),.7], bounds=[(1e-9,100),(1e-9,100),(1e-9,.999)])
print('poisson pure',res0.x,'nll',res0.fun,'AIC',2*2+2*res0.fun)
print('poisson floor',res1.x,'nll',res1.fun,'AIC',2*3+2*res1.fun)
print('poisson delta_AIC pure-floor',(2*2+2*res0.fun)-(2*3+2*res1.fun))"}

